Java Solution
class Solution {
    public boolean isPowerOfThree(int n) {
        if (n < 1) return false;
        return Math.log10(n) / Math.log10(3) % 1 == 0;
    }
}

Solution: 
```python
import datetime

person1 = {'name': 'Person1', 'available': [datetime.time(9, 0), datetime.time(11, 0)], 'duration': 30}
person2 = {'name': 'Person2', 'available': [datetime.time(13, 0), datetime.time(15, 0)], 'duration': 90}
person3 = {'name': 'Person3', 'available': [datetime.time(14, 0), datetime.time(15, 30)], 'duration': 60}

def schedule_meetings(people):
    # Sort the people by their earliest available time
    sorted_people = sorted(people, key=lambda x: x['available'][0])

    # Initialize the schedule with the first person's earliest available time
    schedule = [sorted_people[0]['available'][0]]

    # Loop through each person and find the next available time slot that is not in conflict with any previous person
    for i in range(1, len(sorted_people)):
        current_person = sorted_people[i]
        for j in range(len(current_person['available'])):
            if schedule[-1] + datetime.timedelta(minutes=current_person['duration']) <= current_person['available'][j]:
                schedule.append(current_person['available'][j])
                break
        else:
            continue
        break

    return schedule

print(schedule_meetings([person1, person2, person3]))
```

